    /// `build_tagged_types` is the second line of defense behind `validate_tagged_program`: a table
    /// whose entry is missing must produce a `CodegenError`, never a guessed body or a panic.
    #[test]
    fn tagged_tables_with_a_missing_entry_are_codegen_errors() {
        let ctx = Context::create();
        let defs = vec![hir::TaggedType::Option(Scalar::Tagged(7))];
        let err = build_tagged_types(&ctx, &defs, &[], &[])
            .expect_err("a payload naming an absent entry must fail closed");
        assert!(
            err.to_string().contains("missing an entry or is recursive"),
            "unexpected diagnostic for a missing tagged entry: {err}"
        );
        // A well-formed neighbour still lowers, so the guard rejects the table, not the shape.
        let (shells, by_body) =
            build_tagged_types(&ctx, &[hir::TaggedType::Option(Scalar::Bool)], &[], &[])
                .expect("a complete table must lower");
        assert_eq!(shells.len(), 1);
        assert_eq!(by_body.len(), 1);
    }

    /// A self-referential entry has no finite body. It must be refused rather than send the
    /// children-first walk around its own cycle.
    #[test]
    fn self_referential_tagged_entries_are_codegen_errors() {
        let ctx = Context::create();
        for defs in [
            vec![hir::TaggedType::Option(Scalar::Tagged(0))],
            vec![hir::TaggedType::Result(Scalar::Bool, Scalar::Tagged(0))],
            // Mutual recursion reaches the same guard one level deeper.
            vec![
                hir::TaggedType::Option(Scalar::Tagged(1)),
                hir::TaggedType::Option(Scalar::Tagged(0)),
            ],
        ] {
            let err = build_tagged_types(&ctx, &defs, &[], &[])
                .expect_err("a recursive tagged entry must fail closed");
            assert!(
                err.to_string().contains("missing an entry or is recursive"),
                "unexpected diagnostic for a recursive tagged entry: {err}"
            );
        }
    }

    /// Entries that lower to one body share one identified struct, and the struct is named for the
    /// lowest id in that class — never for whichever entry the children-first walk reached first.
    #[test]
    fn shared_tagged_bodies_are_named_for_their_lowest_id() {
        let ctx = Context::create();
        // Entry 0 is reached only through its child 2, so a traversal-ordered name would be
        // `align.tagged.2`; entry 1 shares that body and is the lowest id in the class.
        let defs = vec![
            hir::TaggedType::Option(Scalar::Tagged(2)),
            hir::TaggedType::Option(Scalar::Str),
            hir::TaggedType::Option(Scalar::String),
        ];
        let (shells, by_body) =
            build_tagged_types(&ctx, &defs, &[], &[]).expect("a complete table must lower");
        assert_eq!(
            shells[1], shells[2],
            "`Option<str>` and `Option<string>` are one LLVM body and must share one struct"
        );
        assert_ne!(shells[0], shells[1], "a distinct body keeps its own struct");
        assert_eq!(
            shells[1]
                .get_name()
                .map(|name| name.to_string_lossy().to_string()),
            Some("align.tagged.1".to_string()),
            "the shared struct must be named for the lowest id in its body class"
        );
        assert_eq!(by_body.len(), 2, "two distinct bodies must index two structs");
    }

    #[test]
    fn malformed_mir_type_graphs_fail_before_llvm_construction() {
        let i32_ty = Ty::Int(IntTy { bits: 32, signed: true });
        let base = || Program {
            sqlite_callback_effects: Default::default(),
            fns: vec![Function {
                name: program_call("main"),
                params: vec![],
                param_modes: vec![],
            borrow_mut_cleanup_slots: vec![],
                return_borrow: hir::ReturnBorrowSummary::None,
                return_region: hir::ReturnRegionSummary::None,
                ret: i32_ty,
                return_cleanup: hir::ReturnCleanupAbi::None,
                slots: vec![],
                slot_align: vec![],
                value_tys: vec![],
                blocks: vec![Block {
                    id: 0,
                    stmts: vec![],
                    stmt_lines: vec![],
                    term: Term::Return(Some(Operand::Const(Const::Int(0, i32_ty)))),
                }],
                entry: 0,
                exportable: false,
            }],
            externs: vec![],
            imported_fns: vec![],
            link_libs: vec![],
            structs: vec![],
            enums: vec![],
            resources: Vec::new(),
            tagged_types: vec![],
            fn_types: vec![],
            tuples: vec![],
        };

        for (name, ty, expected) in [
            (
                "struct",
                Ty::Struct(7),
                "tagged payload struct type id 7 is missing",
            ),
            (
                "sum",
                Ty::Enum(7),
                "tagged payload sum type id 7 is missing",
            ),
            ("tuple", Ty::Tuple(7), "tuple type id 7 is missing"),
            (
                "struct-array",
                Ty::StructArray(7, 2),
                "tagged payload struct type id 7 is missing",
            ),
        ] {
            let mut malformed = base();
            malformed.fns[0].value_tys.push(ty);
            let err = emit_llvm_ir(
                &malformed,
                &BuildTarget::Baseline,
                false,
                &[],
                None,
            )
            .expect_err("a direct missing MIR type id must fail closed");
            assert!(
                err.to_string().contains(expected),
                "{name} produced an unexpected diagnostic: {err}"
            );
        }

        for (name, field_ty) in [
            ("array", Ty::Array(Scalar::Struct(0), 1)),
            ("struct-array", Ty::StructArray(0, 1)),
        ] {
            let mut malformed = base();
            malformed.structs.push(StructDef {
                name: "Cycle".to_string(),
                source_name: "Cycle".to_string(),
                fields: vec![align_sema::FieldDef {
                    name: "next".to_string(),
                    ty: field_ty,
                }],
                align: None,
                c_repr: false,
            });
            let err = emit_llvm_ir(
                &malformed,
                &BuildTarget::Baseline,
                false,
                &[],
                None,
            )
            .expect_err("an array-mediated inline MIR cycle must fail closed");
            assert!(
                err.to_string()
                    .contains("missing or recursive by-value definition"),
                "{name} cycle produced an unexpected diagnostic: {err}"
            );
        }

        let mut header_cycle = base();
        let cyclic_ty = Ty::DynStructArray(0, Layout::Aos);
        header_cycle.structs.push(StructDef {
            name: "HeaderCycle".to_string(),
            source_name: "HeaderCycle".to_string(),
            fields: vec![align_sema::FieldDef {
                name: "next".to_string(),
                ty: cyclic_ty,
            }],
            align: None,
            c_repr: false,
        });
        header_cycle.fns[0].params.push(0);
        header_cycle.fns[0]
            .param_modes
            .push(align_ast::ParamMode::ByValue);
        header_cycle.fns[0].slots.push(cyclic_ty);
        header_cycle.fns[0].ret = cyclic_ty;
        header_cycle.fns[0].return_cleanup = hir::ReturnCleanupAbi::DynamicBit;
        header_cycle.fns[0].return_borrow = hir::ReturnBorrowSummary::Roots {
            params: vec![0],
            captures: vec![],
        };
        header_cycle.fns[0].return_region = hir::ReturnRegionSummary::Roots {
            params: vec![0],
            captures: vec![],
        };
        let err = validate_tagged_program(&header_cycle)
            .expect_err("a header-only recursive graph cannot supply return provenance");
        assert!(
            err.to_string().contains("cannot borrow"),
            "header-mediated capability recursion produced an unexpected diagnostic: {err}"
        );

        let mut shared = base();
        shared.structs.push(StructDef {
            name: "Shared0".to_string(),
            source_name: "Shared0".to_string(),
            fields: vec![align_sema::FieldDef {
                name: "value".to_string(),
                ty: Ty::Bool,
            }],
            align: None,
            c_repr: false,
        });
        for depth in 1..40 {
            let child = (depth - 1) as u32;
            shared.structs.push(StructDef {
                name: format!("Shared{depth}"),
                source_name: format!("Shared{depth}"),
                fields: vec![
                    align_sema::FieldDef {
                        name: "left".to_string(),
                        ty: Ty::Struct(child),
                    },
                    align_sema::FieldDef {
                        name: "right".to_string(),
                        ty: Ty::Struct(child),
                    },
                ],
                align: None,
                c_repr: false,
            });
        }
        shared.fns[0].value_tys.push(Ty::Struct(39));
        validate_tagged_program(&shared)
            .expect("shared acyclic MIR type subgraphs must be memoized and accepted");

        let mut multi_invalid = base();
        multi_invalid.structs.push(StructDef {
            name: "MultiInvalid".to_string(),
            source_name: "MultiInvalid".to_string(),
            fields: vec![
                align_sema::FieldDef {
                    name: "first".to_string(),
                    ty: Ty::Struct(7),
                },
                align_sema::FieldDef {
                    name: "second".to_string(),
                    ty: Ty::Enum(9),
                },
            ],
            align: None,
            c_repr: false,
        });
        let err = validate_tagged_program(&multi_invalid)
            .expect_err("multi-invalid MIR must fail on its first stored child");
        assert!(
            err.to_string()
                .contains("tagged payload struct type id 7 is missing"),
            "the iterative LIFO walk changed stored-child error precedence: {err}"
        );

        const DEEP_GRAPH_LEN: usize = 16_384;
        let mut deep = base();
        deep.structs.reserve(DEEP_GRAPH_LEN);
        for index in 0..DEEP_GRAPH_LEN {
            let ty = if index + 1 == DEEP_GRAPH_LEN {
                Ty::Bool
            } else {
                Ty::Struct((index + 1) as u32)
            };
            deep.structs.push(StructDef {
                name: format!("Deep{index}"),
                source_name: format!("Deep{index}"),
                fields: vec![align_sema::FieldDef {
                    name: "next".to_string(),
                    ty,
                }],
                align: None,
                c_repr: false,
            });
        }
        deep.fns[0].value_tys.push(Ty::Struct(0));
        validate_tagged_program(&deep)
            .expect("a deep acyclic MIR graph must validate without the process stack");

        const DEEP_TAGGED_LEN: usize = 4_096;
        let mut deep_tagged = base();
        deep_tagged.tagged_types.reserve(DEEP_TAGGED_LEN);
        for index in 0..DEEP_TAGGED_LEN {
            let payload = if index == 0 {
                Scalar::Bool
            } else {
                Scalar::Tagged((index - 1) as u32)
            };
            deep_tagged
                .tagged_types
                .push(hir::TaggedType::Option(payload));
        }
        deep_tagged.structs.push(StructDef {
            name: "DeepTagged".to_string(),
            source_name: "DeepTagged".to_string(),
            fields: vec![align_sema::FieldDef {
                name: "value".to_string(),
                ty: Ty::Tagged((DEEP_TAGGED_LEN - 1) as u32),
            }],
            align: None,
            c_repr: false,
        });
        validate_tagged_program(&deep_tagged)
            .expect("a deep source-ABI tagged key must not consume the process stack");
        // `build_tagged_types` claims to be stack-bounded at this depth too, and only building the
        // module proves it: a recursive body walk would overflow here long before the verifier ran.
        emit_llvm_ir(&deep_tagged, &BuildTarget::Baseline, false, &[], None)
            .expect("a deep tagged table must lower without the process stack");

        deep.structs[DEEP_GRAPH_LEN - 1].fields[0].ty = Ty::Struct(0);
        let err = validate_tagged_program(&deep)
            .expect_err("a deep inline MIR cycle must return CodegenError");
        assert!(
            err.to_string()
                .contains("missing or recursive by-value definition"),
            "deep cycle produced an unexpected diagnostic: {err}"
        );
    }

