    #[test]
    fn tuple_drop_uses_recursive_element_destructor() {
        let i32_ty = Ty::Int(IntTy { bits: 32, signed: true });
        let program = Program {
            sqlite_callback_effects: Default::default(),
            fns: vec![Function {
                name: program_call("main"),
                params: vec![],
                param_modes: vec![],
            borrow_mut_cleanup_slots: vec![],
                return_borrow: hir::ReturnBorrowSummary::None,
                return_region: hir::ReturnRegionSummary::None,
                ret: i32_ty,
                return_cleanup: hir::ReturnCleanupAbi::None,
                slots: vec![Ty::Tuple(0)],
                slot_align: vec![None],
                value_tys: vec![],
                blocks: vec![Block {
                    id: 0,
                    stmts: vec![Stmt::DropFlagInit(0), Stmt::Drop(0)],
                    stmt_lines: vec![(0, 0); 2],
                    term: Term::Return(Some(Operand::Const(Const::Int(0, i32_ty)))),
                }],
                entry: 0,
                exportable: false,
            }],
            externs: vec![],
            imported_fns: vec![],
            link_libs: vec![],
            structs: vec![],
            enums: vec![],
            resources: Vec::new(),
            tagged_types: vec![],
            fn_types: vec![],
            tuples: vec![TupleDef {
                elems: vec![Scalar::DynArray(align_sema::PrimScalar::String)],
            }],
        };
        let ir = emit_llvm_ir(&program, &BuildTarget::Baseline, false, &[], None)
            .expect("a tuple with an owned string array must lower");
        assert!(
            ir.contains("call void @align_rt_free_string_array"),
            "tuple Drop must use the deep string-array destructor:\n{ir}"
        );

        let program = Program {
            sqlite_callback_effects: Default::default(),
            fns: vec![Function {
                name: program_call("main"),
                params: vec![],
                param_modes: vec![],
            borrow_mut_cleanup_slots: vec![],
                return_borrow: hir::ReturnBorrowSummary::None,
                return_region: hir::ReturnRegionSummary::None,
                ret: i32_ty,
                return_cleanup: hir::ReturnCleanupAbi::None,
                slots: vec![Ty::Tuple(0)],
                slot_align: vec![None],
                value_tys: vec![],
                blocks: vec![Block {
                    id: 0,
                    stmts: vec![Stmt::DropFlagInit(0), Stmt::Drop(0)],
                    stmt_lines: vec![(0, 0); 2],
                    term: Term::Return(Some(Operand::Const(Const::Int(0, i32_ty)))),
                }],
                entry: 0,
                exportable: false,
            }],
            externs: vec![],
            imported_fns: vec![],
            link_libs: vec![],
            structs: vec![StructDef {
                name: "MoveElem".to_string(),
                source_name: "MoveElem".to_string(),
                fields: vec![align_sema::FieldDef {
                    name: "text".to_string(),
                    ty: Ty::String,
                }],
                align: None,
                c_repr: false,
            }],
            enums: vec![],
            resources: Vec::new(),
            tagged_types: vec![],
            fn_types: vec![],
            tuples: vec![TupleDef {
                elems: vec![Scalar::DynStructArray(0)],
            }],
        };
        let ir = emit_llvm_ir(&program, &BuildTarget::Baseline, false, &[], None)
            .expect("a tuple with an owned Move-struct array must lower");
        assert!(
            ir.contains("dropdeep.head") && ir.contains("dropdeep.ep"),
            "tuple Drop must iterate and recursively drop array<Move-struct> elements:\n{ir}"
        );
        assert!(
            ir.matches("call void @align_rt_free").count() >= 2,
            "tuple Drop must free both each owned element field and the outer array buffer:\n{ir}"
        );
    }

    #[test]
    fn noncanonical_nested_tagged_tables_fail_closed() {
        let i32_ty = Ty::Int(IntTy { bits: 32, signed: true });
        let i64_scalar = Scalar::Int(IntTy { bits: 64, signed: true });
        let program = |tagged_types: Vec<hir::TaggedType>, value_tys: Vec<Ty>| Program {
            sqlite_callback_effects: Default::default(),
            fns: vec![Function {
                name: program_call("main"),
                params: vec![],
                param_modes: vec![],
            borrow_mut_cleanup_slots: vec![],
                return_borrow: hir::ReturnBorrowSummary::None,
                return_region: hir::ReturnRegionSummary::None,
                ret: i32_ty,
                return_cleanup: hir::ReturnCleanupAbi::None,
                slots: vec![],
                slot_align: vec![],
                value_tys,
                blocks: vec![Block {
                    id: 0,
                    stmts: vec![],
                    stmt_lines: vec![],
                    term: Term::Return(Some(Operand::Const(Const::Int(0, i32_ty)))),
                }],
                entry: 0,
                exportable: false,
            }],
            externs: vec![],
            imported_fns: vec![],
            link_libs: vec![],
            structs: vec![],
            enums: vec![],
            resources: vec![],
            tagged_types,
            fn_types: vec![],
            tuples: vec![],
        };
        let cases = [
            (
                "unreachable",
                program(
                    vec![hir::TaggedType::Option(i64_scalar)],
                    vec![],
                ),
            ),
            (
                "duplicate",
                program(
                    vec![
                        hir::TaggedType::Option(i64_scalar),
                        hir::TaggedType::Option(i64_scalar),
                    ],
                    vec![Ty::Tagged(0), Ty::Tagged(1)],
                ),
            ),
            (
                "source-ordered",
                program(
                    vec![
                        hir::TaggedType::Result(i64_scalar, Scalar::Bool),
                        hir::TaggedType::Option(i64_scalar),
                    ],
                    vec![Ty::Tagged(0), Ty::Tagged(1)],
                ),
            ),
        ];
        for (name, program) in cases {
            let err = emit_llvm_ir(
                &program,
                &BuildTarget::Baseline,
                false,
                &[],
                None,
            )
            .expect_err("a malformed nested tagged table must fail closed");
            assert!(
                err.to_string()
                    .contains("not compact, unique, and canonical"),
                "{name} table produced an unexpected diagnostic: {err}"
            );
        }
    }

    /// `print` of a value that is not an int / float / str / bool / char. Sema's `print_kind` gate
    /// rejects every one of these, but codegen used to dispatch on the type with a **catch-all
    /// integer tail**, so an aggregate reaching it asked a `{ ptr, i64 }` / `[3 x i64]` / `%P` value
    /// for its `IntValue` and aborted the compiler. It must be a `CodegenError`.
    #[test]
    fn print_of_an_unprintable_value_is_an_error_not_a_panic() {
        let i64_ty = Ty::Int(IntTy { bits: 64, signed: true });
        let struct_def = StructDef {
            name: "P".to_string(),
            source_name: "P".to_string(),
            fields: vec![align_sema::FieldDef { name: "x".to_string(), ty: i64_ty }],
            align: None,
            c_repr: false,
        };
        let cases: &[(&str, Ty, Vec<StructDef>)] = &[
            ("array", Ty::Array(Scalar::Int(IntTy { bits: 64, signed: true }), 3), vec![]),
            ("struct", Ty::Struct(0), vec![struct_def]),
            ("slice", Ty::Slice(Scalar::Int(IntTy { bits: 64, signed: true })), vec![]),
        ];
        for (name, ty, structs) in cases {
            let err = codegen_program(
                vec![
                    Stmt::Let(0, Rvalue::Load(0)),
                    Stmt::Let(1, Rvalue::Call(DirectCall::Runtime(RuntimeKey::Print), vec![Operand::Value(0)])),
                ],
                vec![*ty, Ty::Unit],
                vec![*ty],
                structs.clone(),
                vec![],
                vec![],
            )
            .expect_err(&format!("print of a `{name}` must not reach the runtime call"));
            let text = err.to_string();
            assert_eq!(
                text,
                "lowering failed: callable metadata invalid:InvalidGraph",
                "`print({name})` must fail in callable preflight"
            );
        }
    }

    /// A malformed MIR `ValueId` use of a `()`-returning call. Source lowering emits the void call
    /// for its effects but returns `Const::Unit` to every value context, so this shape is now only a
    /// defensive codegen invariant test. It must remain a `CodegenError`, never a map-index panic.
    #[test]
    fn a_malformed_unit_value_id_is_an_error_not_a_panic() {
        let unit_fn = Function {
            name: program_call("u"),
            params: vec![],
            param_modes: vec![],
            borrow_mut_cleanup_slots: vec![],
            return_borrow: hir::ReturnBorrowSummary::None,
            return_region: hir::ReturnRegionSummary::None,
            ret: Ty::Unit,
            return_cleanup: hir::ReturnCleanupAbi::None,
            slots: vec![],
            slot_align: vec![],
            value_tys: vec![],
            blocks: vec![Block { id: 0, stmts: vec![], stmt_lines: vec![], term: Term::Return(None) }],
            entry: 0,
            exportable: false,
        };
        let err = codegen_program(
            vec![
                Stmt::Let(0, Rvalue::Call(direct_program("u"), vec![])),
                Stmt::Let(1, Rvalue::Use(Operand::Value(0))),
            ],
            vec![Ty::Unit, Ty::Unit],
            vec![],
            vec![],
            vec![],
            vec![unit_fn],
        )
        .expect_err("a `()` operand has no LLVM value and must not be read from the value map");
        let text = err.to_string();
        assert!(
            text.contains("has no LLVM value"),
            "the missing-value read must say so, got: {text}"
        );
    }

    #[test]
    fn malformed_parallel_mir_cannot_publish_a_region_capability() {
        let i32_ty = Ty::Int(IntTy { bits: 32, signed: true });
        let spawn_error = codegen_program(
            vec![Stmt::Let(
                0,
                Rvalue::SpawnTask {
                    tg: Operand::Const(Const::Unit),
                    closure: Operand::Const(Const::Unit),
                    capture_tys: vec![Ty::ArenaHandle],
                    r: i32_ty,
                    fallible: false,
                },
            )],
            vec![Ty::Box(Scalar::Int(IntTy { bits: 32, signed: true }))],
            vec![],
            vec![],
            vec![],
            vec![],
        )
        .expect_err("spawn metadata must reject a direct region capability before publication");
        assert_lowering(
            spawn_error,
            "spawn worker metadata contains a non-Send region capability",
        );

        let i64_ty = Ty::Int(IntTy { bits: 64, signed: true });
        let source_ty = Ty::Slice(Scalar::Int(IntTy { bits: 64, signed: true }));
        let par_error = codegen_program(
            vec![
                Stmt::Let(0, Rvalue::Load(0)),
                Stmt::Let(1, Rvalue::Load(1)),
                Stmt::Let(
                    2,
                    Rvalue::ParMapReduce {
                        src: Operand::Value(0),
                        func: program_call("unreachable_worker"),
                        captures: vec![Operand::Value(1)],
                        capture_tys: vec![Ty::ArenaHandle],
                        elem_in: i64_ty,
                        elem_out: i64_ty,
                        work_weight: 1,
                    },
                ),
            ],
            vec![source_ty, Ty::ArenaHandle, i64_ty],
            vec![source_ty, Ty::ArenaHandle],
            vec![],
            vec![],
            vec![],
        )
        .expect_err("par_map metadata must reject a direct region capability before publication");
        assert_lowering(par_error, "callable metadata invalid:InvalidGraph");
    }

